// Port of supabase/functions/send-daily-motivation-email.
// Cron job, once a day: writes today's motivational message (one per UTC date, generated by an AI
// gateway if it does not exist yet), then emails it to every account that has not received it today.
//
// Authorisation: `Authorization: Bearer <CRON_SECRET>`. (The original had no check.)
// Config (env): LOVABLE_API_KEY, LOVABLE_API_URL (optional override), and mail settings read by
// functions/_shared/mail.js (MAIL_MODE, SMTP_*). Dry-run mail is the default.
//
// Deliberate difference: the original listed only the first page of auth users (50). This port reads
// all accounts that have an email.
import express from "express";
import { query } from "../_shared/db.js";
import { sendMail } from "../_shared/mail.js";

const DEFAULT_AI_URL = "https://ai.gateway.lovable.dev/v1/chat/completions";
const BATCH_SIZE = 10;
const FALLBACK_SUBJECT = "🌟 Your Daily Dose of Motivation from SimpleLecture";
const FALLBACK_BODY = "Keep learning, keep growing! Every step you take brings you closer to your goals. We believe in you. — Team SimpleLecture";

export const router = express.Router();

const escapeHtml = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);

function emailHtml(userName, messageBody) {
  // The message body is inserted as HTML, as in the original. It is generated text, not user input.
  return `
    <div style="font-family: 'Segoe UI', Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 0; background-color: #ffffff;">
      <div style="background: linear-gradient(135deg, #6366f1 0%, #8b5cf6 100%); padding: 40px 30px; text-align: center; border-radius: 0 0 24px 24px;">
        <h1 style="color: #ffffff; margin: 0; font-size: 28px; font-weight: 700;">SimpleLecture</h1>
        <p style="color: rgba(255,255,255,0.85); margin: 8px 0 0; font-size: 14px;">Your Daily Motivation ✨</p>
      </div>
      <div style="padding: 36px 30px;">
        <p style="color: #374151; font-size: 18px; margin: 0 0 8px;">Hi ${escapeHtml(userName)},</p>
        <div style="background-color: #f8f7ff; border-left: 4px solid #6366f1; padding: 20px 24px; margin: 24px 0; border-radius: 0 12px 12px 0;">
          <p style="color: #4b5563; font-size: 16px; line-height: 1.7; margin: 0; font-style: italic;">
            ${messageBody}
          </p>
        </div>
        <div style="text-align: center; margin: 32px 0;">
          <a href="https://simplelecture.com" style="display: inline-block; background: linear-gradient(135deg, #6366f1 0%, #8b5cf6 100%); color: #ffffff; text-decoration: none; padding: 14px 36px; border-radius: 8px; font-size: 16px; font-weight: 600;">
            Continue Learning →
          </a>
        </div>
      </div>
      <div style="padding: 20px 30px; text-align: center; border-top: 1px solid #f3f4f6;">
        <p style="color: #9ca3af; font-size: 12px; margin: 0;">
          You're receiving this because you're part of the SimpleLecture family 💜
        </p>
      </div>
    </div>`;
}

// Asks the AI gateway for today's message. Falls back to a fixed message when the reply is unparseable.
async function generateMessage(today) {
  const apiKey = process.env.LOVABLE_API_KEY;
  if (!apiKey) throw new Error("LOVABLE_API_KEY is not configured");
  const randomSeed = Math.floor(Math.random() * 100000) + 1;

  const aiResponse = await fetch(process.env.LOVABLE_API_URL || DEFAULT_AI_URL, {
    method: "POST",
    headers: { Authorization: `Bearer ${apiKey}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      model: "google/gemini-3-flash-preview",
      messages: [
        {
          role: "system",
          content: `You are SimpleLecture's brand voice. Write a short, warm, inspiring motivational message (3-4 sentences) for students. Each message must be completely original and different. Include a sense of encouragement and emotional connection with the SimpleLecture brand. Sign off warmly as "Team SimpleLecture". Also generate a catchy email subject line.

Respond in this exact JSON format:
{"subject_line": "your subject here", "message_body": "your motivational message here"}`,
        },
        {
          role: "user",
          content: `Generate today's motivational message. Date: ${today}. Random seed: ${randomSeed}. Do NOT repeat any previous messages.`,
        },
      ],
    }),
  });
  if (!aiResponse.ok) {
    console.error("[Daily Motivation] AI gateway error:", aiResponse.status);
    throw new Error(`AI gateway error: ${aiResponse.status}`);
  }

  const aiData = await aiResponse.json();
  const content = aiData.choices?.[0]?.message?.content || "";
  try {
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    if (!jsonMatch) throw new Error("No JSON found in AI response");
    const parsed = JSON.parse(jsonMatch[0]);
    return { subjectLine: parsed.subject_line, messageBody: parsed.message_body };
  } catch {
    console.error("[Daily Motivation] Failed to parse AI response");
    return { subjectLine: FALLBACK_SUBJECT, messageBody: content || FALLBACK_BODY };
  }
}

// Returns today's message, creating it when missing. A concurrent insert (unique violation) is
// resolved by reading the row another instance wrote.
async function todaysMessage(today) {
  const { rows } = await query(
    "SELECT subject_line, message_body FROM public.daily_motivation_messages WHERE message_date = $1::date LIMIT 1",
    [today]
  );
  if (rows[0]) {
    console.log("[Daily Motivation] Reusing existing message for today");
    return { subjectLine: rows[0].subject_line, messageBody: rows[0].message_body };
  }

  console.log("[Daily Motivation] Generating new AI message...");
  const generated = await generateMessage(today);
  try {
    await query(
      "INSERT INTO public.daily_motivation_messages (message_date, subject_line, message_body) VALUES ($1::date, $2, $3)",
      [today, generated.subjectLine, generated.messageBody]
    );
  } catch (err) {
    if (err.code !== "23505") throw err;
    console.log("[Daily Motivation] Message already created by another instance, fetching...");
    const { rows: again } = await query(
      "SELECT subject_line, message_body FROM public.daily_motivation_messages WHERE message_date = $1::date LIMIT 1",
      [today]
    );
    return { subjectLine: again[0].subject_line, messageBody: again[0].message_body };
  }
  console.log("[Daily Motivation] Message generated:", generated.subjectLine);
  return generated;
}

async function logEmail(user, today, messageBody, status, errorMessage) {
  await query(
    `INSERT INTO public.daily_motivation_email_logs (user_id, email, sent_date, ai_message, status, error_message)
     VALUES ($1, $2, $3::date, $4, $5, $6)`,
    [user.id, user.email, today, messageBody, status, errorMessage ?? null]
  );
}

router.all("/", async (req, res) => {
  const json = (status, body) => res.status(status).json(body);
  if (req.method === "OPTIONS") return res.status(200).end();

  const cronSecret = process.env.CRON_SECRET;
  if (!cronSecret) return json(500, { error: "CRON_SECRET is not configured" });
  if (req.headers.authorization !== `Bearer ${cronSecret}`) return json(401, { error: "Unauthorized" });

  try {
    const today = new Date().toISOString().split("T")[0];
    console.log(`[Daily Motivation] Starting for date: ${today}`);

    const { subjectLine, messageBody } = await todaysMessage(today);

    const { rows: users } = await query(
      `SELECT u.id, u.email, p.full_name
         FROM auth.users u
         JOIN public.profiles p ON p.id = u.id
        WHERE u.email IS NOT NULL AND u.email <> ''`
    );
    if (users.length === 0) {
      console.log("[Daily Motivation] No users with emails found");
      return json(200, { message: "No users to email", sent: 0 });
    }
    console.log(`[Daily Motivation] Found ${users.length} users with emails`);

    const { rows: alreadySent } = await query(
      "SELECT user_id FROM public.daily_motivation_email_logs WHERE sent_date = $1::date",
      [today]
    );
    const sentIds = new Set(alreadySent.map((r) => r.user_id));
    const usersToEmail = users.filter((u) => !sentIds.has(u.id));
    console.log(`[Daily Motivation] ${usersToEmail.length} users remaining (${sentIds.size} already sent)`);

    if (usersToEmail.length === 0) {
      return json(200, { message: "All users already emailed today", sent: 0 });
    }

    if ((process.env.MAIL_MODE || "dry-run") === "smtp" && (!process.env.SMTP_HOST || !process.env.SMTP_USER || !process.env.SMTP_PASS)) {
      throw new Error("SMTP credentials not configured");
    }

    let sentCount = 0;
    let failedCount = 0;
    for (let i = 0; i < usersToEmail.length; i += BATCH_SIZE) {
      const batch = usersToEmail.slice(i, i + BATCH_SIZE);
      await Promise.all(
        batch.map(async (user) => {
          try {
            await sendMail({
              to: user.email,
              subject: subjectLine,
              html: emailHtml(user.full_name || "Student", messageBody),
              text: `${subjectLine}\n\n${messageBody}`,
            });
            await logEmail(user, today, messageBody, "sent", null);
            sentCount++;
          } catch (err) {
            console.error(`[Daily Motivation] Failed for ${user.email}:`, err.message);
            failedCount++;
            await logEmail(user, today, messageBody, "failed", (err.message || "").substring(0, 500));
          }
        })
      );
      if (i + BATCH_SIZE < usersToEmail.length) {
        await new Promise((resolve) => setTimeout(resolve, 500));
      }
    }

    console.log(`[Daily Motivation] Done! Sent: ${sentCount}, Failed: ${failedCount}`);
    return json(200, {
      message: "Daily motivation emails processed",
      sent: sentCount,
      failed: failedCount,
      total: usersToEmail.length,
      subject: subjectLine,
    });
  } catch (error) {
    console.error("[Daily Motivation] Fatal error:", error?.message);
    return json(500, { error: error.message || "Internal server error" });
  }
});

export default router;
